import {webkit,devices} from 'playwright';
const browser=await webkit.launch({headless:true});
const page=await browser.newPage({...devices['iPhone 13'],userAgent:devices['iPhone 13'].userAgent+' KAKAOTALK'});
page.setDefaultTimeout(12000);
await page.setContent(`<!doctype html><html><body><div id="modal" class="modal on"><div id="modalSheet" class="sheet"><h3>회원 정보 수정</h3><input id="fmName" value="회원1"><button id="save" class="btn pri">저장</button><button id="cancel" class="btn ghost" onclick="closeModal()">취소</button></div></div><script>window.closeCount=0;window.events28=[];document.addEventListener('touchstart',e=>window.events28.push(['start',e.target?.id,e.target?.className]),true);document.addEventListener('touchend',e=>window.events28.push(['end',e.target?.id,e.target?.className]),true);window.closeModal=function(){window.closeCount++;document.getElementById('modal').classList.remove('on');document.getElementById('modalSheet').innerHTML=''};<\/script></body></html>`);
await page.addScriptTag({path:'app-v5.4-fix28.js'});
await page.waitForFunction(()=>window.__kokmatchModalCancelFix==='28.1');
const cancel=page.locator('#cancel');await cancel.scrollIntoViewIfNeeded();const b=await cancel.boundingBox();if(!b)throw new Error('cancel no box');await page.touchscreen.tap(b.x+b.width/2,b.y+b.height/2);await page.waitForFunction(()=>!document.getElementById('modal').classList.contains('on'));
const result=await page.evaluate(()=>({closeCount:window.closeCount,trace:window.__kokmatchV28Last,html:document.getElementById('modalSheet').innerHTML,events:window.events28}));
console.log('RESULT',JSON.stringify(result));if(result.closeCount!==1)throw new Error('close called '+result.closeCount+' times');if(result.html!=='')throw new Error('modal sheet not cleared');if(result.trace!=='수정 취소 완료')throw new Error('unexpected trace '+result.trace);if(!result.events.some(e=>e[0]==='start'&&e[1]==='cancel'))throw new Error('touchstart missing '+JSON.stringify(result.events));console.log('PASS V28.1 IOS TOUCH CANCEL');
await browser.close();